  ('loreto-mexico', '10S', 'Loreto', 'Mexico', 'Blue whales and five empty islands', 'live', 'verified', 'mountainValley', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","tropical","diveglobal","romance"}', '{"tropical"}', '{"essential","premier"}', null, null, '{"key_facts":["Loreto Bay sheltered by 5 uninhabited islands (Coronado, del Carmen, Danzante, Monserrat, Santa Catalina); marine park w/ 40+ dive/snorkel sites (Source: wildloreto.com, 2026-07-04)","Blue-whale season ~Jan-Mar, strongest early Feb to mid-Mar (Source: thoroughlytravel.com, 2026-07-04)","Humpback, fin, sei whales + dolphins, rays, sea lions, turtles also frequent the bay (Source: thoroughlytravel.com, 2026-07-04)","Whale tours depart Loreto Marina / Marina Puerto Escondido, 4-6 h (Source: sallysees.com, 2026-07-04)","LTO airport served by Alaska/American/Volaris/WestJet; no non-stop LTO-SJD (Source: flightsfrom.com, 2026-07-04)"],"safety":{"emergency":"911","nearest_trauma":"Loreto clinics for routine; serious trauma/recompression to La Paz (~350 km) or Los Cabos","malaria":"none","dengue":"present in Baja California Sur (Loreto ~2 cases YTD 2026, low); use repellent","water":"bottled/purified","hurricane":"May 15-Nov 30, peak Aug-Oct","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}]},"timing":{"peak":"Dec-Apr (whale season; blue whale Feb-Apr; dry mild high season)","shoulder":"May, Oct-Nov","green":"Jun-Sep (hot, hurricane-exposed, best rates)","out_of_season_fill":"summer island-snorkel, kayak, TPC golf packages","fire_date":"early fall (Sep-Oct) for Jan-Mar whale window; summer green-season golf/island campaigns","event_peaks":["Blue Whale Festival (whale season)","US/Canada winter escape peak","Danzante Bay golf invitational (autumn)"],"booking_lead":"3-6 months for whale-season stays + panga slots; resort peak weeks further out"},"jewels":[{"status":"live","tier":"premier","commission":"operator agreement","name":"Blue-whale watching","si":"expedition","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary","romance":"destination","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"essential","commission":"operator","name":"Sierra de la Giganta / mission-canyon hike","si":"expedition","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["expedition"],"shelf_fit":{"diveglobal":"destination","expedition":"primary","romance":"destination","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"essential","commission":"operator","name":"Isla Coronado snorkel day","si":"tropical","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","tropical"],"shelf_fit":{"diveglobal":"evidenced","expedition":"destination","romance":"destination","tropical":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"essential","commission":"operator","name":"Isla del Carmen / Puerto Balandra snorkel","si":"tropical","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","tropical"],"shelf_fit":{"diveglobal":"evidenced","expedition":"destination","romance":"destination","tropical":"primary"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"live","tier":"premier","commission":"resort/operator","name":"Isla Danzante / Danzante Bay","si":"tropical","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["tropical"],"shelf_fit":{"diveglobal":"destination","expedition":"destination","romance":"destination","tropical":"primary"},"commission_lane":["operator","hotel"],"commission_embedded":false,"commission_basis":"lane"},{"status":"future","tier":"premier","commission":"operator agreement","name":"Loreto Bay Marine Park dives (40+ sites)","si":"diveglobal","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","expedition":"destination","romance":"destination","tropical":"destination"},"commission_lane":["operator"],"commission_embedded":false,"commission_basis":"lane"},{"status":"future","tier":"premier","commission":"resort contract","name":"Villa del Palmar spa + Danzante Bay golf escape","si":"romance","wells":["stay","activities"],"wells_basis":"derived from name/blurb/hook","si_all":["romance"],"shelf_fit":{"diveglobal":"destination","expedition":"destination","romance":"primary","tropical":"destination"},"commission_lane":["hotel"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"When is the best time to see blue whales in Loreto?","a":"Roughly January–March, strongest early February to about mid-March, because that''s when blue whales feed in the bay; gray and humpback come slightly earlier. Tours are 4–6-hour pangas from Loreto Marina or Puerto Escondido — book the short window 3–6 months ahead.","source":"thoroughlytravel.com / sallysees.com, 2026-07-04","si_tag":"expedition","accessed":"2026-07-04"},{"q":"What are Loreto''s islands like?","a":"Five uninhabited islands — Coronado, del Carmen, Danzante, Monserrat and Santa Catalina — shelter the bay with turquoise coves, white-sand beaches and a sea-lion colony, all inside a protected marine park with 40+ snorkel/dive sites. Isla Coronado is the classic day trip.","source":"wildloreto.com, 2026-07-04","si_tag":"tropical","accessed":"2026-07-04"},{"q":"Is Loreto good for a golf-and-spa couples escape?","a":"Yes, if you want premier rather than ultra. Villa del Palmar at Danzante Bay has Mexico''s only TPC course (Best Golf Course in Mexico 2020) and a 39,000-sq-ft spa on a secluded bay — position it as a premier golf-and-whale escape, not an Aman-tier ultra.","source":"villadelpalmarloreto.com, 2026-07-04","si_tag":"romance","accessed":"2026-07-04"},{"q":"What''s the real risk to plan for — is the diving remote?","a":"Yes — chamber distance is the gatekeeper. Loreto has local clinics for routine care, but a serious dive bend routes ~350 km south to the La Paz chamber (or Los Cabos), so dive conservatively, keep whale-panga trips to licensed no-chase operators, and observe 18–24 h no-fly before the LTO departure.","source":"scubaboard.com / dan.org, 2026-07-04","si_tag":"safety","accessed":"2026-07-04"}],"seo":{"meta_title":"Loreto Mexico — Blue Whales, Marine Park & Island Snorkel | TravelWell.World","meta_description":"Loreto, Baja California Sur: blue-whale season, five uninhabited islands, Loreto Bay Marine Park diving, TPC Danzante Bay golf. Pueblo Magico gateway, plan by season.","long_tail":["best time to see blue whales in Loreto","Loreto whale watching tours 2026","Isla Coronado snorkel","TPC Danzante Bay golf","Villa del Palmar Loreto"],"search_language":"es-MX","local_keywords":["avistamiento de ballena azul Loreto","Parque Nacional Bahia de Loreto","islas de Loreto","buceo Loreto","Pueblo Magico Loreto","tours de ballenas Loreto"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]},"primary_keyword":["Loreto Mexico","blue whale watching Loreto","Loreto Bay National Park","Loreto islands"]},"booking":{"advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":["expedition","tropical","diveglobal","romance"],"ultra":[{"what":"Villa del Palmar at the Islands of Loreto by Danzante Bay (premier, not true ultra)","why_ultra":"Mexico''s only TPC course (Rees Jones; Best Golf Course in Mexico 2020), 39,000-sq-ft spa, secluded bay","earning":"on application / via host-Virtuoso if preferred program exists (verify — not confirmed Virtuoso)","virtuoso_value_add":"resort credit/upgrade where preferred program applies; else standard commission via bedbank/MoR","mor":"resale under resort contract; position as premier golf + whale escape, not Aman/FS-tier ultra; nearest true ultra = Los Cabos/East Cape"}],"source_verified":"2026-07-04","hero":{"query":"Loreto, Mexico"},"geo":{"lat":26.0115,"lng":-111.3486},"orbit":[{"id":"balandra-beach-mexico","jewels":5,"si":["tropical","family","romance"]},{"id":"cabo-pulmo-mexico","jewels":5,"si":["expedition","diveglobal"]},{"id":"cabo-san-lucas-mexico","jewels":6,"si":["liveaboard","expedition","ocean","ultra"]},{"id":"east-cape-mexico","jewels":7,"si":["romance","expedition","diveglobal","ocean"]},{"id":"espiritu-santo-island-mexico","jewels":5,"si":["expedition","ocean"]},{"id":"la-paz-mexico","jewels":6,"si":["expedition","tropical","diveglobal"]},{"id":"los-barriles-mexico","jewels":8,"si":["ocean","expedition","tropical"]},{"id":"magdalena-bay-mexico","jewels":5,"si":["expedition","ocean"]},{"id":"san-jose-del-cabo-mexico","jewels":5,"si":["romance","expedition","culture","ocean"]},{"id":"todos-santos-mexico","jewels":6,"si":["expedition","culture","wellness","ocean"]}],"orbit_country":["akumal-mexico","bacalar-mexico","calakmul-mexico","campeche-city-mexico","cancun-mexico","careyes-mexico","celestun-mexico","chapala-ajijic-mexico","chichen-itza-mexico","coba-mexico","costalegre-mexico","cozumel-mexico","ensenada-mexico","guadalajara-mexico","guanajuato-city-mexico","holbox-mexico","huatulco-mexico","isla-contoy-mexico","isla-mujeres-mexico","izamal-mexico","mahahual-mexico","mazamitla-mexico","merida-mexico","mexico-city-mexico","oaxaca-city-mexico","palenque-mexico","playa-del-carmen-mexico","puerto