  ('los-barriles-mexico', '10S', 'Los Barriles', 'Mexico', 'Los Barriles kiteboarding', 'live', 'verified', 'tropicalBeach', 'Baja California Sur (Los Cabos & La Paz)', '{"ocean","expedition","tropical"}', '{"tropical"}', '{"comfort","premier"}', null, null, '{"key_facts":["East Cape town on the Sea of Cortez, ~1 hr from Los Cabos Airport / ~40 min from La Paz","El Norte kite/wind season Nov 1 - end of March; N/NE crosswind 15-30 knots, afternoon peak","Offshore sportfishing peaks May-early November (marlin, sailfish, dorado, wahoo, tuna); glass-calm","Dorado Shoot Out (~mid-July, ~140 boats) is the largest dorado tournament in Baja; East Cape Offshore / Bisbee''s circuit opener nearby","Villas + fishing lodges are the lodging rung (Van Wormer Palmas de Cortez / Playa del Sol); northern gateway to Cabo Pulmo"],"safety":{"emergency":"911","hospital":"remote small town, no major trauma on-site; La Paz ~40 min (Hospital Salvatierra/private) or Los Cabos/San Jose del Cabo ~1 hr (private) - FLAG MEDEVAC DISTANCE; carry medical + evac insurance","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"drink bottled/purified water","hurricane":"Jun-Nov - trip insurance for summer/fall","wind_watersport":"El Norte 15-30 kt with offshore-drift risk - lessons with rescue-boat cover, correct kite size, helmet/impact vest for beginners","offshore_fishing":"open Sea of Cortez - licensed charter, VHF, life jackets, float plan, sun/heat protection; slow rescue on remote coast","dive":"diving south at Cabo Pulmo (separate dossier); nearest hyperbaric chamber Los Cabos or La Paz; no-fly 18-24h; DAN +1-919-684-9111; remote-distance flag","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never c