otá (NOT Medellín)","note":"Do not misassign to Medellín","program":"n/a","price_tier":"$$$$"}],"source_verified":null,"hero":{"query":"Medellín & Antioquia, Colombia, Colombia"},"geo":{"lat":6.2442,"lng":-75.5812},"orbit":[{"id":"bogota-colombia","jewels":12,"si":["romance","adventure","culture","culinary"]}],"orbit_country":["cartagena-colombia","san-andres-colombia"]}'::jsonb, 67),
