  ('monteverde-costa-rica', '10S', 'Monteverde', 'Costa Rica', 'The original cloud forest', 'live', 'verified', 'mountainValley', 'Costa Rica', '{"expedition","wildlife","romance"}', '{}', '{"essential","premier","ultra"}', null, null, '{"key_facts":["Birthplace of the commercial canopy zipline; Selvatura runs 13 ziplines incl. a 1 km line, 15 platforms, Tarzan swing, and 8 hanging bridges (51-170 m long, 12-60 m high).","Cloud forest protects 400+ bird species (resplendent quetzal, three-wattled bellbird), 2,500+ plants incl. 500+ orchids, 100+ mammals.","Three reserves: Monteverde Cloud Forest ($25, 7AM-4PM), Santa Elena (quieter, great quetzals), Curi-Cancha (least crowded, top birding).","Resplendent quetzal breeds Feb-Jun (peak Mar-Apr), best viewed 6-9 AM on wild-avocado trees.","Highland ~1,400 m; ~3-4 hr from SJO with a rough, partly-unpaved final mountain road; dengue risk low at elevation."],"safety":{"emergency":"911","nearest_clinic":"Santa Elena local clinics (minor/first response)","major_trauma":"San Jose hospitals (CIMA, Clinica Biblica), ~3-4 hr by road; air/ground evac pathway","advisory_reason":"Crime (petty nationwide; some violent crime, concentrated in specific San Jose neighborhoods)","advisory_issued":"2026-04-02","standard_caution":"No valuables in parked rental cars; registered operators; daylight driving on mountain road","activity_hazards":["zipline/canopy operator certification + harness/brakes + weight limits","mountain-road fog + unpaved sections (4WD, daylight)","night-walk footing + vipers (guided only)","wet suspension-bridge decking + heights"],"air_access_verified":"SJO (Juan Santamaria) ~3-4 hr road; note rough/partly-unpaved access road","water":"Tap water generally potable including Monteverde area; bottled optional for sensitive travelers","dengue":"Low at ~1,400 m highland elevation; use repellent","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-09-01T16:20:27Z","page