  ('oaxaca-city-mexico', '10S', 'Oaxaca City & the Central Valleys', 'Mexico', 'High valley of mezcal and markets', 'live', 'verified', 'kyoto', 'Oaxaca (Oaxaca City & Coast)', '{"culinary","culture","expedition","romance"}', '{}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Dual UNESCO World Heritage: Historic Centre of Oaxaca + Monte Alban, jointly inscribed 1987","Santiago Matatlan is the recognized World Capital of Mezcal, ~45 min SE on the Ruta Caminos del Mezcal","Teotitlan del Valle: ~2,500-year living Zapotec weaving tradition, natural cochineal/indigo/marigold dyes, rugs $75–$500","Tlacolula Sunday market: longest continuously running market in Mesoamerica, 1,000+ vendors","El Tule (Santa Maria del Tule): the world''s widest tree, a ~2,000-year-old Montezuma cypress"],"safety":{"emergency":"911","hospitals":["Clinica Hospital Carmen (Calle M. Abasolo 215)","Hospital Reforma (Calle Reforma 613)"],"medevac":"Air ambulance staged at OAX; serious cases transferred to Mexico City (MEX)","advisory_note":"Oaxaca City / Monte Alban / Puerto Escondido / Huatulco explicitly carry no US-gov-employee restrictions","air_access_verified":true,"airport":"OAX (Xoxocotlan International)","altitude_m":1555,"altitude_note":"~1,550–1,555 m (mild)","water":"bottled/purified","other_risks":["Hierve el Agua cliff-edge footing + periodic Jun–Oct closures","high-proof mezcal + rural driving (use driver)","high-valley UV/heat on all-day circuits"],"fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-09-04T12:02:56Z","page_updated":"2026-09-04T00:25:51+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bri